# Function to compute flow_signal based on FII and DII today net flows
def run(context):
	fii_net_today = context['fii_net_today']
	dii_net_today = context['dii_net_today']

	if fii_net_today > 0 and dii_net_today > 0:
		return 'Strong Positive'
	elif fii_net_today < 0 and dii_net_today < 0:
		return 'Strong Negative'
	else:
		return 'Neutral'
